<script setup lang="ts">
import {ref,watch} from 'vue'
import {api} from './api'
import Results from './Results.vue'
const props=defineProps<{competitionId:string;teams:any[];stages:any[];matches:any[]}>()
const draft=ref<any>(null),error=ref(''),busy=ref(false),validation=ref<any>(),reason=ref(''),preview=ref<any>(),history=ref<any[]>([])
const sponsors=ref<any[]>([]),partners=ref<any[]>([]),prizes=ref<any[]>([]),allocations=ref<any[]>([])
const config=ref<any>({display_meta:{},seal_mode:'monogram'}),placements=ref<any[]>([]),path=ref<string[]>([])
const sponsor=ref<any>({active:true,name:'',english_name:'',logo_url:'',introduction:''})
const partner=ref<any>({sponsor_id:'',tier:'official',category:'',published:true,display_order:0})
const prize=ref<any>({name:'',provider_partner_id:'',category:'equipment',model_code:'',unit:'件',description:'',builtin_illustration_key:'',image_url:'',active:true})
const base=()=>'/admin/competitions/'+props.competitionId
const endpoint=()=>base()+'/final-results'
async function run(fn:()=>Promise<any>){error.value='';busy.value=true;try{await fn()}catch(e:any){error.value=e.message+(e.details?' '+JSON.stringify(e.details):'')}finally{busy.value=false}}
async function refresh(){validation.value=null
 try{draft.value=await api(endpoint()+'/draft');config.value={display_meta:{},seal_mode:'monogram',...draft.value.config};placements.value=draft.value.placements;path.value=draft.value.path.sort((a:any,b:any)=>a.display_order-b.display_order).map((x:any)=>x.match_id);history.value=await api(endpoint()+'/releases')}catch(e:any){if(e.status!==404)throw e;draft.value=null;placements.value=[];path.value=[];history.value=[];config.value={display_meta:{},seal_mode:'monogram'}}
 ;[sponsors.value,partners.value,prizes.value]=await Promise.all([api('/admin/sponsors'),api(base()+'/partners'),api(base()+'/prizes')])
 if(draft.value&&placements.value.length){const d=await api(endpoint()+'/preview');allocations.value=d.allocations.map((a:any)=>({...a}))}else allocations.value=[]
}
watch(()=>props.competitionId,()=>run(refresh),{immediate:true})
async function save(){await run(async()=>{await api(endpoint()+'/draft','PUT',{...config.value,expected_version:draft.value?.version||1});await refresh()})}
async function mutate(suffix:string,method:string,payload:any){await api(endpoint()+suffix,method,{...payload,expected_version:draft.value.version});await refresh()}
async function upload(ev:Event,obj:any,key:string){const f=(ev.target as HTMLInputElement).files?.[0];if(!f)return;await run(async()=>{const fd=new FormData();fd.append('file',f);obj[key]=(await api('/admin/assets','POST',fd)).url})}
const name=(id:string)=>props.teams.find(t=>t.id===id)?.name||id
async function showPreview(){await run(async()=>preview.value=await api(endpoint()+'/preview'))}
async function publish(){await run(async()=>{await api(endpoint()+'/publish','POST',{expected_version:draft.value.version,expected_source_fingerprint:validation.value.source_fingerprint,reason:reason.value}, {'Idempotency-Key':crypto.randomUUID()});await refresh()})}
</script>
<template>
<section><h1>最终排名与奖励</h1><p>维护工作稿 → 计算名次 → 合作方与奖品 → 分配 → 预览与校验 → 发布。工作稿修改不会覆盖公开版本。重新计算名次会清空奖励分配，请在录入分配前完成计算。</p>
<el-alert v-if="error" :title="error" type="error" :closable="false"/>
<p>工作稿版本 {{draft?.version||'未建档'}} · {{draft?.current_release_id?'已有公开版本':'暂无有效公开版本'}}</p>
<el-form label-position="top"><div class="form-grid">
<el-form-item label="最终阶段"><el-select v-model="config.final_stage_id"><el-option v-for="s in stages" :key="s.id" :value="s.id" :label="s.name"/></el-select></el-form-item>
<el-form-item label="实际总决赛 / 重置赛（首次计算可留空）"><el-select v-model="config.final_match_id" clearable><el-option v-for="m in matches.filter(m=>!m.group&&m.bracket!=='third')" :key="m.id" :value="m.id" :label="m.code+' '+name(m.a)+' / '+name(m.b)"/></el-select></el-form-item>
<el-form-item label="赛季展示名称"><el-input v-model="config.display_meta.edition_label"/></el-form-item><el-form-item label="纪念章环文"><el-input v-model="config.display_meta.seal_edition_label"/></el-form-item><el-form-item label="纪念章编号"><el-input v-model="config.display_meta.seal_serial"/></el-form-item>
<el-form-item label="纪念章标识"><el-select v-model="config.seal_mode"><el-option value="monogram" label="队伍缩写"/><el-option value="team_logo" label="上传队标"/></el-select></el-form-item></div>
<el-button :loading="busy" @click="save">保存 / 创建工作稿</el-button><el-button :disabled="!draft||busy" @click="run(()=>mutate('/calculate','POST',{}))">生成候选名次</el-button></el-form>
<template v-if="draft">
<h2>名次与领取资格</h2><p>无季军赛时保留并列 3–4。人工变更时选择“裁定”并说明理由。资料版本默认为决定性比赛的名单版本。</p>
<el-table :data="placements"><el-table-column label="队伍"><template #default="s">{{name(s.row.registration_id)}}</template></el-table-column><el-table-column label="起 / 止" min-width="210"><template #default="s"><el-input-number v-model="s.row.rank_from" :min="1" :max="32" size="small"/><el-input-number v-model="s.row.rank_to" :min="1" :max="32" size="small"/></template></el-table-column><el-table-column label="资料版本"><template #default="s"><el-input-number v-model="s.row.team_display_version" :min="1" size="small"/></template></el-table-column><el-table-column label="来源"><template #default="s"><el-select v-model="s.row.source_method"><el-option value="calculated" label="计算"/><el-option value="ruling" label="裁定"/></el-select></template></el-table-column><el-table-column label="领取范围 / 人数" min-width="200"><template #default="s"><el-select v-model="s.row.eligibility_policy"><el-option value="starters_only" label="正式成员"/><el-option value="full_roster" label="全名单"/><el-option value="explicit_count" label="自定人数"/></el-select><el-input-number v-model="s.row.recipient_count" :min="0"/></template></el-table-column><el-table-column label="裁定 / 品牌版本原因" min-width="180"><template #default="s"><el-input v-model="s.row.ruling_reason" placeholder="裁定原因"/><el-input v-model="s.row.display_version_reason" placeholder="品牌版本原因"/></template></el-table-column></el-table>
<el-button @click="run(()=>mutate('/placements','PUT',{items:placements}))">保存全部名次（清空奖励分配）</el-button>
<h2>冠军路径</h2><el-select v-model="path" multiple style="width:100%"><el-option v-for="m in matches.filter(m=>m.confirmed)" :key="m.id" :value="m.id" :label="m.code+' '+name(m.a)+' / '+name(m.b)"/></el-select><p>{{path.map(id=>matches.find(m=>m.id===id)?.code).join(' → ')}}</p><el-button @click="run(()=>mutate('/path','PUT',{items:path.map(id=>({match_id:id,stage_label:matches.find(m=>m.id===id)?.code}))}))">保存路径顺序</el-button>
<h2>品牌库</h2><el-select placeholder="编辑已有品牌" @change="(id:string)=>sponsor={...sponsors.find(s=>s.id===id)}"><el-option v-for="s in sponsors" :key="s.id" :value="s.id" :label="s.name"/></el-select><div class="form-grid"><el-input v-model="sponsor.name" placeholder="品牌中文名"/><el-input v-model="sponsor.english_name" placeholder="英文名"/><el-input v-model="sponsor.official_url" placeholder="官网 HTTPS（可空）"/><el-input v-model="sponsor.introduction" type="textarea" placeholder="品牌介绍"/></div><label>上传品牌 Logo <input type="file" accept="image/png,image/jpeg,image/webp" @change="upload($event,sponsor,'logo_url')"></label><img v-if="sponsor.logo_url" :src="sponsor.logo_url" width="80" alt="品牌预览"><el-checkbox v-model="sponsor.active">启用</el-checkbox><el-button @click="run(async()=>{await api('/admin/sponsors'+(sponsor.id?'/'+sponsor.id:''),sponsor.id?'PATCH':'POST',{...sponsor,expected_version:sponsor.version});sponsor={name:'',active:true};await refresh()})">保存品牌</el-button>
<h2>本届合作关系</h2><div class="toolbar"><el-select v-model="partner.sponsor_id" placeholder="选择品牌"><el-option v-for="s in sponsors" :key="s.id" :value="s.id" :label="s.name"/></el-select><el-select v-model="partner.tier"><el-option value="presenting" label="首席赞助商"/><el-option value="official" label="合作伙伴"/></el-select><el-input v-model="partner.category" placeholder="合作类别"/><el-input-number v-model="partner.display_order"/><el-checkbox v-model="partner.published">公开</el-checkbox><el-button @click="run(async()=>{await api(partner.id?'/admin/competition-partners/'+partner.id:base()+'/partners',partner.id?'PATCH':'POST',{...partner,expected_version:draft.version});partner={tier:'official',published:true};await refresh()})">保存合作项</el-button></div><el-button v-for="p in partners" :key="p.id" @click="partner={...p}">{{sponsors.find(s=>s.id===p.sponsor_id)?.name}} · {{p.tier}}</el-button>
<h2>赛事奖品</h2><div class="form-grid"><el-input v-model="prize.name" placeholder="产品名称"/><el-input v-model="prize.model_code" placeholder="型号"/><el-input v-model="prize.unit" placeholder="单位"/><el-select v-model="prize.provider_partner_id" placeholder="提供方"><el-option v-for="p in partners" :key="p.id" :value="p.id" :label="sponsors.find(s=>s.id===p.sponsor_id)?.name"/></el-select><el-select v-model="prize.category"><el-option value="equipment" label="外设"/><el-option value="commemorative" label="纪念品"/></el-select><el-select v-model="prize.builtin_illustration_key" clearable placeholder="内置类型插画"><el-option v-for="x in ['headset','keyboard','mouse']" :key="x" :value="x" :label="x"/></el-select><el-input v-model="prize.description" type="textarea" placeholder="奖品描述"/></div><label>上传产品图 <input type="file" accept="image/png,image/jpeg,image/webp" @change="upload($event,prize,'image_url')"></label><img v-if="prize.image_url" :src="prize.image_url" width="100" alt="产品预览"><el-checkbox v-model="prize.active">启用</el-checkbox><el-button @click="run(async()=>{await api(prize.id?'/admin/prizes/'+prize.id:base()+'/prizes',prize.id?'PATCH':'POST',{...prize,expected_version:draft.version});prize={name:'',category:'equipment',unit:'件',active:true};await refresh()})">保存奖品</el-button><el-button v-for="z in prizes" :key="z.id" @click="prize={...z}">{{z.name}}</el-button>
<h2>奖励分配</h2><div v-for="(a,i) in allocations" :key="i" class="toolbar"><el-select v-model="a.placement_id" placeholder="获奖队伍"><el-option v-for="p in placements" :key="p.id" :value="p.id" :label="name(p.registration_id)"/></el-select><el-select v-model="a.prize_id" placeholder="奖品"><el-option v-for="z in prizes" :key="z.id" :value="z.id" :label="z.name"/></el-select><el-select v-model="a.distribution"><el-option value="per_team" label="按队"/><el-option value="per_recipient" label="按人"/></el-select><label>总数 <el-input-number v-model="a.quantity" :min="1"/></label><label v-if="a.distribution==='per_recipient'">每人数 <el-input-number v-model="a.per_recipient_quantity" :min="1"/></label><el-button @click="allocations.splice(i,1)">移除</el-button></div><el-button @click="allocations.push({quantity:1,distribution:'per_team',per_recipient_quantity:1})">添加分配</el-button><el-button @click="run(()=>mutate('/allocations','PUT',{items:allocations}))">保存全部分配</el-button>
<h2>预览与发布</h2><div class="toolbar"><el-button @click="showPreview">内部预览</el-button><el-button @click="run(async()=>validation=await api(endpoint()+'/validate','POST',{expected_version:draft.version}))">校验发布条件</el-button></div><div v-if="validation"><p>源哈希 {{validation.source_fingerprint}}</p><el-alert v-for="v in validation.blocking_errors" :key="v.message" :title="v.message" type="error" :closable="false"/><el-alert v-if="!validation.blocking_errors.length" title="可发布" type="success" :closable="false"/></div><el-input v-model="reason" placeholder="发布 / 修订 / 撤回原因"/><el-button type="primary" :disabled="busy||!reason||!validation||!!validation.blocking_errors.length" @click="publish">正式发布新版本</el-button><el-button :disabled="!draft.current_release_id||!reason||busy" @click="run(()=>mutate('/withdraw','POST',{reason}))">撤回公开版本</el-button>
<h2>发布历史</h2><el-table :data="history"><el-table-column prop="release_number" label="版本"/><el-table-column prop="status" label="状态"/><el-table-column prop="published_at" label="发布时间"/><el-table-column prop="reason" label="原因"/><el-table-column prop="invalidation_reason" label="失效说明"/></el-table>
</template>
<el-dialog v-model="preview" title="内部预览（未公开）" width="95%" destroy-on-close><div v-if="preview?.champion&&preview?.final_match" class="public-site results-page v5-motion-on"><Results :preview-data="preview"/></div><p v-else>请先计算名次并选择实际终局比赛。</p></el-dialog>
</section>
</template>
